#pragma once
static bool ReadSourceEnvironmentModel(unsigned hash,EnvironmentModel& out){try{
 using namespace w2v2disk;char key[24];sprintf_s(key,"model/%08x",hash);auto data=SourceBytes(22,key);auto s=w2source::validateModel(data);need(s.hash==hash&&s.clusters<=4096,"source motion model identity/count");auto& c=out.cpu;auto& h=c.header;h.magic=Magic;h.version=Version;h.section=hash;h.meshes=s.clusters;memcpy(&h.minimum,data.data()+208,24);
 auto ca=r64(data,72),ma=r64(data,64);
 for(unsigned i=0;i<s.clusters;++i){auto at=size_t(ca+U(i)*96);unsigned material=r32(data,at+4),vc=r32(data,at+8),ic=r32(data,at+12);auto vo=r64(data,at+16),io=r64(data,at+24);Mesh m{};m.texture=r32(data,size_t(ma+U(material)*96+16));m.firstVertex=unsigned(c.vertices.size());m.vertexCount=vc;m.firstIndex=unsigned(c.indices.size());m.indexCount=ic;memcpy(&m.minimum,data.data()+at+64,24);
  need(U(c.vertices.size())+vc<=1000000&&U(c.indices.size())+ic<=3000000,"source motion decoded model cap");for(unsigned j=0;j<vc;++j){EnvironmentVertex v;memcpy(&v,data.data()+size_t(vo+U(j)*40),40);c.gpuVertices.push_back(v);c.vertices.push_back({v.position,v.color,v.u,v.v});c.normals.push_back({v.normal,v.color});}for(unsigned j=0;j<ic;++j)c.indices.push_back(r16(data,size_t(io+U(j)*2)));c.meshes.push_back(m);
 }h.vertices=unsigned(c.vertices.size());h.indices=unsigned(c.indices.size());PrepareShadowIndices(c);PrepareMeshDrawLists(c);return true;
 }catch(const std::exception& error){Log("SOURCE_MOTION_MODEL_REFUSED hash=%08X reason=%s",hash,error.what());return false;}}
static void LoadSourceEnvironmentDynamics(){try{
 using namespace w2v2disk;auto input=SourceInput(51,"environment/motions");need(input.get<unsigned>()==0x31444d57,"source motion magic");auto n=input.get<unsigned>();need(n<=1000,"source motion instances");std::vector<EnvironmentMotion> motions;std::map<unsigned,EnvironmentModel> models;U frames=0,modelBytes=0;
 for(unsigned i=0;i<n;++i){EnvironmentMotion m;input.read(&m.model,20);input.read(m.rotation,12);m.amplitude=input.get<float>();input.read(&m.initial,64);need(m.count<=100000&&m.scale<256&&std::isfinite(m.amplitude),"source motion dimensions");frames+=m.count;need(frames<=1000000,"source motion frame cap");for(auto x:m.rotation)need(std::isfinite(x),"source motion rotation");for(unsigned k=0;k<16;++k)need(std::isfinite((&m.initial._11)[k]),"source motion matrix");m.current=m.initial;m.frames.resize(m.count);input.read(m.frames.data(),size_t(m.count)*64);for(const auto& f:m.frames)for(unsigned k=0;k<16;++k)need(std::isfinite((&f._11)[k]),"source motion frame matrix");
  for(unsigned axis=0;axis<3;++axis)if(m.rotation[axis]!=0&&m.amplitude!=0){unsigned length=unsigned(std::max(0.f,std::floor(2*std::abs(m.amplitude)/(m.rotation[axis]*.13333334f)+.5f)));need(length<=10000,"source motion wave cap");for(unsigned k=0;k<length;++k)m.waves[axis].push_back(std::sin(3.14159274f*k/length)*std::abs(m.amplitude));}
  if(!models.count(m.model)){EnvironmentModel model;need(ReadSourceEnvironmentModel(m.model,model),"source motion model closure");auto& c=model.cpu;modelBytes+=U(c.gpuVertices.size())*40+U(c.vertices.size())*sizeof(Vertex)+U(c.normals.size())*16+U(c.indices.size()+c.shadowIndices.size())*4;need(modelBytes<=64*MiB,"source ambient geometry memory cap");models.emplace(m.model,std::move(model));}motions.push_back(std::move(m));
 }input.end();envMotions=std::move(motions);envModels=std::move(models);InterlockedExchange(&envMotionsReady,1);Log("SOURCE_MOTIONS_ACTIVE instances=%u models=%u frames=%llu cpu_bytes=%llu",n,unsigned(envModels.size()),frames,modelBytes);
 }catch(const std::exception& error){envMotions.clear();envModels.clear();Log("SOURCE_MOTIONS_REFUSED reason=%s",error.what());++v2Failures;}}
